//Genuary #14: Pure black and white. No gray

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-iResolution.xy/2.)/iResolution.y;
    uv *= mat2(1., -1./sqrt(3.), 0., 2./sqrt(3.)) * 10.;

    vec3 g = vec3(uv, 1.-uv.x-uv.y),
    id = floor(g),
    g2 = abs(2.*fract(g)-1.);

    vec3 col = vec3(smoothstep(.1,.12,sin(length(id.z)+length(id*.25)-iTime*3.)));
    col *= g2.x > .95 || g2.y > .95 || g2.z > .95 ? 0. : 1.;

    fragColor = vec4(col,1.0);
}
